<template><div v-if="modelValue" class="overlay" @click.self="close"><div class="dialog" role="dialog" aria-modal="true" :aria-label="title"><div class="dialog-header"><span class="dialog-icon">A</span><h3>{{title}}</h3></div><input ref="input" v-model="text" @keyup.enter="ok" @keyup.esc="close" autocomplete="off"/><div class="buttons"><button class="secondary" type="button" @click="close">Cancel</button><button class="primary" type="button" @click="ok">OK</button></div></div></div></template>
<script setup lang="ts">
import {ref,watch,nextTick} from "vue";const props=defineProps<{modelValue:boolean;title:string;value?:string}>();const emit=defineEmits(["update:modelValue","ok"]);const text=ref(""),input=ref<HTMLInputElement>();
watch(()=>props.modelValue,async show=>{if(show){text.value=props.value??"";await nextTick();input.value?.focus();input.value?.select()}});
function close(){emit("update:modelValue",false)}function ok(){emit("ok",text.value);close()}
</script>
<style scoped>
.overlay{position:fixed;inset:0;z-index:1000;display:flex;justify-content:center;align-items:center;padding:20px;background:#0007;backdrop-filter:blur(2px)}.dialog{width:min(390px,100%);padding:20px;border:1px solid var(--border-strong);border-radius:10px;background:var(--dialog-bg);color:var(--text-1);box-shadow:0 16px 45px #1a273440}.dialog-header{display:flex;align-items:center;gap:10px;margin-bottom:16px}.dialog-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--border);border-radius:7px;background:var(--surface-3);font-family:Georgia,serif;font-weight:700}h3{margin:0;font-size:17px}input{box-sizing:border-box;width:100%;padding:10px 11px;border:1px solid var(--border-strong);border-radius:6px;outline:none;background:var(--input-bg);color:var(--text-1)}.buttons{margin-top:18px;display:flex;justify-content:flex-end;gap:9px}button{min-width:78px;padding:8px 16px;border-radius:6px;cursor:pointer;font-weight:600}.secondary{border:1px solid var(--border-strong);background:var(--button-bg);color:var(--text-2)}.primary{border:1px solid #4f7da3;background:#5d89ae;color:#fff}
</style>